-- Estrutura para centros e vinculos Verum.
alter table public.origens add column if not exists codigo_centro text;
create table if not exists public.centros_filiais (codigo_centro text not null, cnpj text not null, filial_sap_grupo text, uf text, endereco text, cep text, cidade text not null, cidade_chave text not null, nome_resumo text, cnpj_raiz text not null, empresa_codigo text, origem text not null default 'Filiais.ods', primary key (codigo_centro, cnpj), constraint centros_filiais_cnpj_check check (cnpj ~ '^[0-9]{14}$'), constraint centros_filiais_raiz_check check (cnpj_raiz ~ '^[0-9]{8}$'));
create table if not exists public.transportadora_centros_verum (nome_transportadora_chave text not null, nome_transportadora text not null, cnpj_raiz_transportadora text, cnpj_unidade_transportadora text, unidade_negocio text, codigo_centro text not null, canais text, marcadores text, origem text not null default 'carrier-details', primary key (nome_transportadora_chave, cnpj_unidade_transportadora, unidade_negocio, codigo_centro));
